css:
.mz *,.mz *::before,.mz *::after{box-sizing: border-box; margin: 0; padding: 0;}
.mz .mm-tabla{border-collapse: collapse;}
.mz .mm-tabla th,.mz .mm-tabla td{border: 1.5px solid var(--bosque); text-align: center;}
.mz .mm-tabla th{font-family: sans-serif; font-size: 11.5px; background: #f3f3f3; padding: 3px 10px;}
.mz .mm-tabla td{height: 36px; font-size: 19px; font-weight: 700;}
.mz .mm-tabla td.mm-cifras{background: #f3f3f3; letter-spacing: 4px; width: 150px;}
.mz .mm-tabla td.mm-resp{width: 150px;}
.mz .serie-cajas{display: flex; gap: 6px; flex-wrap: wrap; font-size: 15px; font-weight: 700; margin-bottom: 9px;}
.mz .serie-cajas .caja-num{width: 56px; height: 38px; border: 1.5px solid var(--bosque); border-radius: 6px; display: flex; align-items: center; justify-content: center;}
.mz .serie-cajas .caja-num.vacia{background: #fff;}
.mz .serie-label{font-size: 12.5px; font-weight: 600; font-family: sans-serif; margin-bottom: 3px;}
.mz .ap-tabla{border-collapse: collapse;}
.mz .ap-tabla th,.mz .ap-tabla td{border: 1.5px solid var(--bosque); text-align: center;}
.mz .ap-tabla th{font-family: sans-serif; font-size: 11.5px; background: #f3f3f3; padding: 3px 8px;}
.mz .ap-tabla td{height: 34px; width: 105px; font-size: 19px; font-weight: 700;}
.mz .ap-tabla td.ap-dado{background: #f3f3f3;}
.mz .desc-fila{display: flex; align-items: center; gap: 8px; font-size: 17px; font-weight: 700; margin-bottom: 8px; flex-wrap: wrap;}
.mz .desc-fila .num-grande{min-width: 60px;}
.mz .desc-fila .caja-sum{width: 76px; height: 34px; border: 1.5px solid var(--bosque); border-radius: 6px;}
.mz .desc-fila .mas{font-family: sans-serif;}
